	/**
	 * 保持するコンテナのListを返します。
	 *
	 * @return コンテナのList
	 */
	public List<MCContainer> getContainers(){
		List<MCContainer> ret = super.getContainers();
		if(!MCCollectionUtil.contains(ret, getCndR())) ret.add(getCndR());
		if(!MCCollectionUtil.contains(ret, getActBulkSetR())) ret.add(getActBulkSetR());
		if(!MCCollectionUtil.contains(ret, getJudgBulkSetR())) ret.add(getJudgBulkSetR());
		if(!MCCollectionUtil.contains(ret, getRsltL())) ret.add(getRsltL());
		if(!MCCollectionUtil.contains(ret, getRsltSmplL())) ret.add(getRsltSmplL());
		if(!MCCollectionUtil.contains(ret, getRsltTtlL())) ret.add(getRsltTtlL());
		if(!MCCollectionUtil.contains(ret, getVldLmtDtSrchL())) ret.add(getVldLmtDtSrchL());
		return ret;
	}

	/**
	 * コンテナに対応したブロックのIDを返します。
	 *
	 * 引数のコンテナに対応するブロックがない場合にはnullを返します。<br>
	 * 引数がnullの場合にはnullを返します。<br>
	 *
	 * @return ブロックID
	 */
	public String getBlockId(MCContainer aCnt){
		if(aCnt == null) return null;
		if(aCnt == getCndR()) return "Cnd";
		if(aCnt == getActBulkSetR()) return "ActBulkSet";
		if(aCnt == getJudgBulkSetR()) return "JudgBulkSet";
		if(aCnt == getRsltL()) return "Rslt";
		if(aCnt == getRsltSmplL()) return "RsltSmpl";
		if(aCnt == getRsltTtlL()) return "RsltTtl";
		if(aCnt == getVldLmtDtSrchL()) return "VldLmtDtSrch";
		return super.getBlockId(aCnt);
	}

	/**
	 * ブロックIDに対応したコンテナを返します。
	 *
	 * 引数のブロックIDに対応するブロックがない場合にはnullを返します。<br>
	 * 引数がnullの場合にはnullを返します。<br>
	 *
	 * @return コンテナ
	 */
	public MCContainer getContainer(String bId){
		if(bId == null) return null;
		if(bId.equals("Cnd")) return getCndR();
		if(bId.equals("ActBulkSet")) return getActBulkSetR();
		if(bId.equals("JudgBulkSet")) return getJudgBulkSetR();
		if(bId.equals("Rslt")) return getRsltL();
		if(bId.equals("RsltSmpl")) return getRsltSmplL();
		if(bId.equals("RsltTtl")) return getRsltTtlL();
		if(bId.equals("VldLmtDtSrch")) return getVldLmtDtSrchL();
		return super.getContainer(bId);
	}

