	/**
	 * この画面のステータスを設定します。
	 *
	 * @param status ステータス
	 */
	public void setStatus(String status) {
		super.setStatus(status);
		if (SRCH_UPD.equals(status)) {
			setSRCH_UPDStatus();
		}
		else if (UPD.equals(status)) {
			setUPDStatus();
		}
		else if (SRCH_JUDG.equals(status)) {
			setSRCH_JUDGStatus();
		}
		else if (JUDG.equals(status)) {
			setJUDGStatus();
		}
		else if (SRCH_DEL.equals(status)) {
			setSRCH_DELStatus();
		}
		else if (DEL.equals(status)) {
			setDELStatus();
		}
		else if (SRCH_DEL_JUDG.equals(status)) {
			setSRCH_DEL_JUDGStatus();
		}
		else if (DEL_JUDG.equals(status)) {
			setDEL_JUDGStatus();
		}
		else if (SRCH_REF.equals(status)) {
			setSRCH_REFStatus();
		}
		else if (REF.equals(status)) {
			setREFStatus();
		}
		else if (SRCH_PRNT_RSLT.equals(status)) {
			setSRCH_PRNT_RSLTStatus();
		}
		else if (PRNT_RSLT.equals(status)) {
			setPRNT_RSLTStatus();
		}
	}

