	/**
	 * リストを保持する画面部品のリストを返します。
	 */
	public MCList getList(MCEventBeans combo, MCRow row, MCEventInfo info) {
		MCList list = super.getList(combo, row, info);
		if(list != null) return list;
		if(combo == Cnd_site_cd) return getCnd_site_cd(row, info);
		if(combo == Cnd_mfg_loc_cd) return getCnd_mfg_loc_cd(row, info);
		if(combo == Cnd_sppl_cd) return getCnd_sppl_cd(row, info);
		if(combo == Cnd_maker_cd) return getCnd_maker_cd(row, info);
		if(combo == Cnd_insp_typ) return getCnd_insp_typ(row, info);
		if(combo == Cnd_insp_ptn_cd) return getCnd_insp_ptn_cd(row, info);
		if(combo == Cnd_insp_mtd_typ) return getCnd_insp_mtd_typ(row, info);
		if(combo == Cnd_insp_aprv_sts_typ) return getCnd_insp_aprv_sts_typ(row, info);
		if(combo == Cnd_itm_p_PPanel.Itm_itm_cd) return getCnd_itm_p_PPanel_Itm_itm_cd(row, info);
		if(combo == Cnd_itm_p_PPanel.Itm_itm_sub1) return getCnd_itm_p_PPanel_Itm_itm_sub1(row, info);
		if(combo == Cnd_itm_p_PPanel.Itm_itm_sub2) return getCnd_itm_p_PPanel_Itm_itm_sub2(row, info);
		if(combo == Cnd_itm_p_PPanel.Itm_itm_sub3) return getCnd_itm_p_PPanel_Itm_itm_sub3(row, info);
		if(combo == Cnd_lot_no) return getCnd_lot_no(row, info);
		if(combo == Cnd_sublot_no) return getCnd_sublot_no(row, info);
		if(combo == Cnd_inst_usr_cd) return getCnd_inst_usr_cd(row, info);
		if(combo == Cnd_inst_dpt_cd) return getCnd_inst_dpt_cd(row, info);
		if(combo == Cnd_act_usr_cd) return getCnd_act_usr_cd(row, info);
		if(combo == Cnd_act_dpt_cd) return getCnd_act_dpt_cd(row, info);
		if(combo == Cnd_judg_usr_cd) return getCnd_judg_usr_cd(row, info);
		if(combo == Cnd_judg_dpt_cd) return getCnd_judg_dpt_cd(row, info);
		if(combo == ActBulkSet_act_usr_dpt_p_PPanel.UsrDpt_dpt_cd) return getActBulkSet_act_usr_dpt_p_PPanel_UsrDpt_dpt_cd(row, info);
		if(combo == JudgBulkSet_judg_usr_dpt_p_PPanel.UsrDpt_dpt_cd) return getJudgBulkSet_judg_usr_dpt_p_PPanel_UsrDpt_dpt_cd(row, info);
		if(combo == columnRslt_insp_mtd_typ) return getRslt_insp_mtd_typ(row, info);
		if(combo == columnRslt_insp_typ) return getRslt_insp_typ(row, info);
		if(combo == columnRslt_insp_ptn_cd) return getRslt_insp_ptn_cd(row, info);
		if(combo == columnRslt_insp_judg_rslt_typ) return getRslt_insp_judg_rslt_typ(row, info);
		if(combo == columnRslt_quality_typ) return getRslt_quality_typ(row, info);
		if(combo == columnRslt_gd_cd) return getRslt_gd_cd(row, info);
		if(combo == columnRslt_dfct_rsn_cd) return getRslt_dfct_rsn_cd(row, info);
		if(combo == Rslt_act_usr_cd_p_PPanel.columnUsrDpt_dpt_cd) return getRslt_act_usr_cd_p_PPanel_columnUsrDpt_dpt_cd(row, info);
		if(combo == Rslt_judg_usr_cd_p_PPanel.columnUsrDpt_dpt_cd) return getRslt_judg_usr_cd_p_PPanel_columnUsrDpt_dpt_cd(row, info);
		if(combo == columnRsltSmpl_base_unit_cd) return getRsltSmpl_base_unit_cd(row, info);
		if(combo == columnRsltSmpl_pack_xfr_pack_unit_cd) return getRsltSmpl_pack_xfr_pack_unit_cd(row, info);
		if(combo == columnRsltSmpl_loc_cd) return getRsltSmpl_loc_cd(row, info);
		if(combo == RsltSmpl_str_ln_p_PPanel.columnStrLn_str_ln_cd) return getRsltSmpl_str_ln_p_PPanel_columnStrLn_str_ln_cd(row, info);
		if(combo == columnRsltSmpl_bd_dpt_cd) return getRsltSmpl_bd_dpt_cd(row, info);
		if(combo == columnRsltTtl_quality_typ) return getRsltTtl_quality_typ(row, info);
		if(combo == columnRsltTtl_gd_cd) return getRsltTtl_gd_cd(row, info);
		if(combo == columnRsltTtl_dfct_rsn_cd) return getRsltTtl_dfct_rsn_cd(row, info);
		if(combo == columnRsltTtl_pack_unit_cd) return getRsltTtl_pack_unit_cd(row, info);
		return null;
	}

	/**
	 * ActionPerformedイベントが実行されたときに呼び出されます。
	 *
	 * @param ap ActionPerformedイベントが実行されたGUI部品
	 */
	public void doAPEvent(MCAPBeans ap, MCEventInfo info) {
		super.doAPEvent(ap, info);
		if (ap == Ctrl_ctrl_PPanel.Ope_srch) doCtrl_ctrl_Ope_srch(info);
		else if (ap == RPnl_dwnld) doRPnl_dwnld(info);
		else if (ap == BtnTtl_rdel) doBtnTtl_rdel(info);
		else if (ap == BtnTtl_rcopy) doBtnTtl_rcopy(info);
		else if (ap == Btn_open_MSBFP0040) doBtn_open_MSBFP0040(info);
		else if (ap == Btn_open_MSBFP0050) doBtn_open_MSBFP0050(info);
		else if (ap == Btn_open_MSBFP0070) doBtn_open_MSBFP0070(info);
		else if (ap == Btn_prnt_insp_rslt) doBtn_prnt_insp_rslt(info);
		else if (ap == Btn_select_all) doBtn_select_all(info);
		else if (ap == Btn_deselect_all) doBtn_deselect_all(info);
		else if (ap == Btn_upd) doBtn_upd(info);
		else if (ap == Btn_upd_judg) doBtn_upd_judg(info);
		else if (ap == Btn_del_inst) doBtn_del_inst(info);
		else if (ap == Btn_del_aprv) doBtn_del_aprv(info);
	}

